// 비공개 원본의 확정 이력 검증기. 금액 재계산·확정·응답·지급은 하지 않습니다.
function adminHistoryScopeMatches(value, scope = adminSettlementHistoryScope()) {
  const received = value?.scope || {};
  return String(received.branchId || "") === scope.branchId
    && String(received.coachRoleId || "") === scope.coachRoleId
    && String(received.settlementMonth || "").slice(0, 10) === scope.settlementMonth;
}

function adminHistoryPayloadIsExact(value, scope = adminSettlementHistoryScope()) {
  if (!value || typeof value !== "object" || Array.isArray(value) || !adminHistoryScopeMatches(value, scope)) return false;
  const remoteState = String(value.state || "").toUpperCase();
  if (remoteState === "EMPTY") {
    return value.snapshot == null && value.confirmation == null && value.reconciliation == null;
  }
  if (!["PENDING", "ACKNOWLEDGED", "DISPUTED"].includes(remoteState)) return false;
  const snapshot = value.snapshot || {};
  const confirmation = value.confirmation || {};
  const reconciliation = value.reconciliation;
  const totals = snapshot.totals || {};
  const displayedTotalsAreExact = [
    totals.settledSessions,
    totals.settledMinutes,
    totals.totalSettlementAmount,
  ].every((item) => typeof item === "number" && Number.isFinite(item) && item >= 0);
  const exactSnapshot = Boolean(
    snapshot.snapshotId
    && Number.isInteger(snapshot.revision)
    && snapshot.revision > 0
    && String(snapshot.status || "").toLowerCase() === "calculated"
    && ["r3_monthly_settlement_v1", "r3_effective_settlement_v2"].includes(String(snapshot.calculationVersion || ""))
    && /^[0-9a-f]{64}$/i.test(String(snapshot.sourceFingerprint || ""))
    && displayedTotalsAreExact
    && confirmation.confirmationId
    && String(confirmation.status || "").toLowerCase() === "confirmed"
    && String(confirmation.confirmationVersion || "") === "r3_monthly_settlement_confirmation_v1"
    && !Number.isNaN(Date.parse(String(confirmation.confirmedAt || "")))
  );
  if (!exactSnapshot) return false;
  if (remoteState === "PENDING") return reconciliation == null;
  const responseReason = normalizeAdminHistoryReason(reconciliation?.reason || "");
  const responseIsExact = remoteState === "ACKNOWLEDGED"
    ? !responseReason
    : !adminHistoryReasonError(responseReason);
  return Boolean(
    reconciliation?.reconciliationId
    && String(reconciliation.status || "").toUpperCase() === remoteState
    && String(reconciliation.responseVersion || "") === "r3_monthly_settlement_coach_reconciliation_v1"
    && !Number.isNaN(Date.parse(String(reconciliation.respondedAt || "")))
    && responseIsExact
  );
}

function adminHistoryReasonError(value = "") {
  const reason = normalizeAdminHistoryReason(value);
  const length = Array.from(reason).length;
  if (length < 2 || length > 240) return "이의 사유를 2~240자로 입력해 주세요.";
  if (
    /[<>\u0000-\u001F\u007F]/.test(reason)
    || reason.includes("@")
    || /(?:https?:\/\/|www\.|javascript:|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i.test(reason)
    || /\d(?:[\s().+\-]*\d){6,}/.test(reason)
  ) return "개인정보나 연락처·링크를 제외하고 확인할 항목만 적어 주세요.";
  return "";
}

function normalizeAdminHistoryReason(value = "") {
  return String(value || "")
    .normalize("NFKC")
    .replace(/[\u200B-\u200F\u202A-\u202E\u2060\u2066-\u2069\uFEFF]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function adminSettlementHistoryScope() {
  return { branchId: String(activeOperationBranchId() || ""), coachRoleId: String(adminSettlementHistory.coachRoleId || ""), settlementMonth: `${state.billingMonth}-01` };
}

function adminSettlementHistoryCoaches() {
  const branchId = activeOperationBranchId();
  const entries = operationBranchCoaches().filter((coach) => coach.serverRoleId && coach.branchId === branchId && coach.status !== "inactive");
  if (new Set(entries.map((coach) => String(coach.serverRoleId))).size !== entries.length) return [];
  return entries;
}

function adminSettlementHistoryScopeKey(scope = adminSettlementHistoryScope()) {
  return [scope.branchId, scope.coachRoleId, scope.settlementMonth].join(":");
}

function adminSettlementHistoryPayloadIsExact(value, scope) {
  if (value?.ok !== true || !adminHistoryScopeMatches(value, scope)) return false;
  if (value.state === "EMPTY") return value.snapshot == null && value.confirmation == null && value.reconciliation == null;
  // 계산만 된 스냅샷은 확정 이력으로 표시하지 않습니다.
  if (value.state === "CALCULATED") return value.confirmation == null && value.reconciliation == null;
  if (value.state !== "CONFIRMED") return false;
  const responseState = value.reconciliation == null ? "PENDING" : String(value.reconciliation.status || "").toUpperCase();
  return adminHistoryPayloadIsExact({ ...value, state: responseState }, scope);
}

// 확정 이력은 메모리에만 보관합니다. 미리보기와 저장 상태를 공유하지 않습니다.
const adminSettlementHistory = { coachRoleId: "", key: "", request: 0, loading: false, value: null, message: "코치를 선택한 뒤 확정 이력을 조회해 주세요.", sessionToken: "", profileId: "" };

function resetAdminSettlementHistory() {
  adminSettlementHistory.request += 1;
  adminSettlementHistory.loading = false;
  adminSettlementHistory.value = null;
  adminSettlementHistory.key = "";
  adminSettlementHistory.sessionToken = "";
  adminSettlementHistory.profileId = "";
  adminSettlementHistory.message = "코치를 선택한 뒤 확정 이력을 조회해 주세요.";
}

function adminSettlementHistoryAccessReady() {
  return operationsRole() === "admin" && operationsAccessReady() && adminApprovalReady() && !adminPinNeedsSetup() && (!isAdminViewLocked("billing") || isAdminUnlocked()) && !adminDemoMode;
}

async function readMonthlySettlementConfirmation(scope, expectedSourceFingerprint = "") {
  return window.TennisNoteDataClient.rpc("tn_admin_monthly_settlement_scope_state", {
    target_branch_id: scope.branchId,
    target_coach_role_id: scope.coachRoleId,
    target_month: scope.settlementMonth,
    expected_source_fingerprint: expectedSourceFingerprint,
  });
}

async function refreshAdminSettlementHistory() {
  const scope = adminSettlementHistoryScope();
  const client = window.TennisNoteDataClient;
  const token = client?.getSession?.()?.access_token || "";
  const profileId = String(adminImportAuthState.profile?.id || "");
  const eligible = adminSettlementHistoryCoaches().filter((coach) => String(coach.serverRoleId) === scope.coachRoleId);
  if (!adminSettlementHistoryAccessReady() || !profileId || !token || !client?.rpc || eligible.length !== 1 || !/^\d{4}-(0[1-9]|1[0-2])-01$/.test(scope.settlementMonth)) {
    resetAdminSettlementHistory();
    adminSettlementHistory.message = "관리자 권한·잠금·지점과 정확한 코치를 먼저 확인해 주세요.";
    renderAdminSettlementHistory();
    return false;
  }
  const key = adminSettlementHistoryScopeKey(scope);
  if (adminSettlementHistory.loading && adminSettlementHistory.key === key && adminSettlementHistory.sessionToken === token && adminSettlementHistory.profileId === profileId) return false;
  const request = ++adminSettlementHistory.request;
  Object.assign(adminSettlementHistory, { key, loading: true, value: null, message: "확정 이력을 확인하고 있습니다.", sessionToken: token, profileId });
  renderAdminSettlementHistory();
  const current = () => request === adminSettlementHistory.request && key === adminSettlementHistoryScopeKey() && token === client.getSession?.()?.access_token && profileId === String(adminImportAuthState.profile?.id || "") && adminSettlementHistoryAccessReady() && adminSettlementHistoryCoaches().filter((coach) => String(coach.serverRoleId) === scope.coachRoleId).length === 1;
  try {
    const value = await readMonthlySettlementConfirmation(scope);
    if (!current()) return false;
    if (!adminSettlementHistoryPayloadIsExact(value, scope)) throw Error("history_scope_invalid");
    adminSettlementHistory.value = value.state === "CONFIRMED" ? value : null;
    adminSettlementHistory.message = value.state === "CONFIRMED" ? "확정 당시 계산본입니다. 현재 예상 정산과 구분되며 이 화면에서 확정·지급하지 않습니다." : value.state === "CALCULATED" ? "계산본은 있으나 아직 확정되지 않았습니다." : "선택한 월의 확정 이력이 없습니다.";
    return true;
  } catch (error) {
    if (current()) { adminSettlementHistory.value = null; adminSettlementHistory.message = "확정 이력을 불러오지 못했습니다. 권한·네트워크와 대상 범위를 확인한 뒤 다시 조회해 주세요."; }
    return false;
  } finally {
    if (request === adminSettlementHistory.request) {
      if (!current()) resetAdminSettlementHistory();
      adminSettlementHistory.loading = false;
      renderAdminSettlementHistory();
    }
  }
}

function renderAdminSettlementHistory() {
  const section = $("#adminSettlementHistory");
  if (!section) return;
  const scope = adminSettlementHistoryScope();
  const token = window.TennisNoteDataClient?.getSession?.()?.access_token || "";
  const eligible = adminSettlementHistoryCoaches();
  const ready = adminSettlementHistoryAccessReady() && Boolean(token) && Boolean(adminImportAuthState.profile?.id);
  if (!ready || (adminSettlementHistory.key && (adminSettlementHistory.key !== adminSettlementHistoryScopeKey(scope) || adminSettlementHistory.sessionToken !== token || adminSettlementHistory.profileId !== String(adminImportAuthState.profile?.id || ""))) || (scope.coachRoleId && eligible.filter((coach) => String(coach.serverRoleId) === scope.coachRoleId).length !== 1)) resetAdminSettlementHistory();
  const select = $("#adminSettlementHistoryCoach");
  const options = [{ serverRoleId: "", name: eligible.length ? "코치 선택" : "조회 가능한 코치 없음" }, ...eligible];
  const optionKey = JSON.stringify(options.map((coach) => [String(coach.serverRoleId), String(coach.name || "코치")]));
  if (select.dataset.options !== optionKey) {
    select.replaceChildren(...options.map((coach) => {
      const option = document.createElement("option"); option.value = String(coach.serverRoleId); option.textContent = String(coach.name || "코치"); return option;
    }));
    select.dataset.options = optionKey;
  }
  select.value = scope.coachRoleId;
  select.disabled = !ready || adminSettlementHistory.loading;
  const button = $("#adminSettlementHistoryRead");
  button.disabled = !ready || !select.value || adminSettlementHistory.loading;
  button.textContent = adminSettlementHistory.loading ? "조회 중" : "확정 이력 조회";
  section.setAttribute("aria-busy", String(adminSettlementHistory.loading));
  $("#adminSettlementHistoryMessage").textContent = !ready ? "관리자 로그인과 잠금 해제 후 조회할 수 있습니다." : adminSettlementHistory.message;
  const details = $("#adminSettlementHistoryDetails");
  details.replaceChildren();
  const value = adminSettlementHistory.value;
  details.hidden = !value;
  if (!value) return;
  const snapshot = value.snapshot;
  const totals = snapshot.totals;
  const rows = [
    ["확정 정산", `${money.format(totals.totalSettlementAmount)}원`],
    ["진행 수업", `${totals.settledSessions}회 · ${totals.settledMinutes}분`],
    ["계산 계약", snapshot.calculationVersion === "r3_monthly_settlement_v1" ? "기존 v1 계산본" : "적용일별 v2 계산본"],
    ["계산본", `revision ${snapshot.revision} · ${snapshot.sourceFingerprint.slice(0, 8)}`],
    ["확정 시각", new Intl.DateTimeFormat("ko-KR", { dateStyle: "short", timeStyle: "short", timeZone: "Asia/Seoul" }).format(new Date(value.confirmation.confirmedAt))],
    ["코치 응답", value.reconciliation?.status === "ACKNOWLEDGED" ? "확인 완료" : value.reconciliation?.status === "DISPUTED" ? "이의 접수" : "응답 대기"],
  ];
  if (value.reconciliation?.reason) rows.push(["이의 사유", normalizeAdminHistoryReason(value.reconciliation.reason)]);
  for (const [label, content] of rows) {
    const dt = document.createElement("dt"); const dd = document.createElement("dd"); dt.textContent = label; dd.textContent = content; details.append(dt, dd);
  }
}

$("#adminSettlementHistoryCoach")?.addEventListener("change", (event) => {
  resetAdminSettlementHistory();
  adminSettlementHistory.coachRoleId = event.target.value;
  renderAdminSettlementHistory();
});
$("#adminSettlementHistoryRead")?.addEventListener("click", () => void refreshAdminSettlementHistory());

/* 기존 월 정산 상세 안의 읽기 전용 이력. 별도 메뉴·금융 행동 없음. */
.admin-settlement-history { margin-top: 20px; padding-top: 16px; border-top: 1px solid var(--line, #ddd); min-width: 0; }
.admin-settlement-history-controls { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 8px; }
.admin-settlement-history-controls label { grid-column: 1 / -1; }
.admin-settlement-history-controls select { width: 100%; min-height: 44px; font-size: 16px; min-width: 0; max-width: 100%; }
.admin-settlement-history-controls button { min-height: 44px; white-space: normal; }
.admin-settlement-history p, .admin-settlement-history dd { overflow-wrap: anywhere; }
.admin-settlement-history dl { display: grid; grid-template-columns: minmax(70px, 1fr) minmax(0, 2fr); gap: 8px; }
.admin-settlement-history dl[hidden] { display: none; }
.admin-settlement-history dd { margin: 0; }
@media (max-width: 600px) { .admin-settlement-history-controls { grid-template-columns: minmax(0, 1fr); } }

